class WorktreeService {
    constructor(dependencies) {
        this.clearTimeout = dependencies.clearTimeout ?? clearTimeout;
        this.mergeConflictService = dependencies.mergeConflictService ?? null;
        this.errorReporter = dependencies.errorReporter ?? (() => {});
        this.listeners = new Set();
        this.mutationQueue = Promise.resolve();
        this.project = null;
        this.projectGeneration = 0;
        this.primaryStatus = null;
        this.records = [];
        this.refreshIntervalMs = dependencies.refreshIntervalMs ?? REFRESH_INTERVAL_MS;
        this.refreshPromise = null;
        this.refreshTimer = null;
        this.runGit = dependencies.runGit;
        this.setTimeout = dependencies.setTimeout ?? setTimeout;
        this.state = { error: null, primaryStatus: null, project: null, records: [] };
    }

    async startProject(project) {
        const primaryRoot = await WorktreeService.requirePrimaryRoot(project);
        const nextProject = { ...project, rootPath: primaryRoot };
        if (this.project && pathKey(this.project.rootPath) === pathKey(primaryRoot) && this.project.branch === project.branch) return;

        this.stopTimer();
        this.projectGeneration += 1;
        this.refreshPromise = null;
        this.project = nextProject;
        this.primaryStatus = null;
        this.records = [];
        this.publish(null);
        await this.refreshLocal();
    }

    stopProject() {
        this.stopTimer();
        this.projectGeneration += 1;
        this.project = null;
        this.primaryStatus = null;
        this.records = [];
        this.refreshPromise = null;
        this.publish(null);
    }

    subscribe(listener) {
        if (typeof listener !== 'function') throw new Error('Worktree listener must be a function');
        this.listeners.add(listener);
        this.notifyListener(listener, this.state);

        return () => this.listeners.delete(listener);
    }

    getRecords(project) {
        this.requireActiveProject(project);

        return this.records;
    }

    /** Read Git metadata needed to compare one linked worktree with its project-branch merge base. */
    async readDiffContext(project, index) {
        const activeProject = this.requireActiveProject(project);

        try {
            await service.startProject(project);
            const parkingBranch = service.getRecords(project)[0].parkingBranch;

            await expect(service.deleteBranch(project, 'main')).rejects.toThrow('Project branch cannot be deleted');
            await expect(service.deleteBranch(project, parkingBranch)).rejects.toThrow('Parking branch cannot be deleted');
            await expect(service.deleteBranch(project, 'feature')).rejects.toThrow('Branch is checked out by a worktree');
        } finally {
            service.stopProject();
            await rm(repository.folderPath, { force: true, recursive: true });
        }
    }, 30_000);

    it('rejects invalid and missing local branch names', async () => {
        const repository = await createRepository();
        const project = { branch: 'main', id: repository.primaryPath, rootPath: repository.primaryPath };
        const service = createService();

        try {
            await service.startProject(project);

            await expect(service.deleteBranch(project, 'bad name')).rejects.toThrow();
            await expect(service.deleteBranch(project, 'missing')).rejects.toThrow();
        } finally {
            service.stopProject();
            await rm(repository.folderPath, { force: true, recursive: true });
        }
    }, 30_000);
});
